import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { randomUUID } from 'node:crypto';
import YAML from 'yaml';
import { getConfigPath } from '../config/load';
import { ConfigSchema, WorkspaceBindingSchema } from '../config/schema';
import { backupWorkspaceConfiguration } from './backup';
import { assertNoSymlink, verifyWorkspaceFiles, workspacePath } from './provision';

/** Explicitly remove only unused, unmodified profiles generated by the retired provisioner. */
export function migrateWorkspaceProfiles(dryRun = true): {
  removed: string[];
  root?: string;
  dryRun: boolean;
  backup?: string;
} {
  const file = getConfigPath();
  assertNoSymlink(file);
  const stat = fs.lstatSync(file);
  if (!stat.isFile() || stat.size > 4 * 1024 * 1024)
    throw new Error('Invalid migration configuration file.');
  const before = fs.readFileSync(file),
    document = YAML.parseDocument(before.toString());
  const raw = document.toJS();
  const root = raw.settings?.workspaceRoot || path.join(os.homedir(), 'agent-workspaces');
  const removed: string[] = [];
  for (const [name, value] of Object.entries(raw.profiles || {})) {
    if (!value || typeof value !== 'object' || !('workspace' in value)) continue;
    const profile = value as { executable: string; cwd: string; workspace: unknown };
    const binding = WorkspaceBindingSchema.parse(profile.workspace);
    const expected = `workspace-${binding.project}-${binding.role}${binding.instance ? `-${binding.instance}` : ''}`;
    if (
      name !== expected ||
      profile.executable !== 'devin' ||
      Object.keys(profile).sort().join(',') !== 'cwd,executable,workspace' ||
      profile.cwd !== workspacePath(binding, root)
    )
      throw new Error(
        `Profile ${name} was modified or is not generated; preserve it and plan an explicit session migration.`
      );
    verifyWorkspaceFiles(binding, root);
    removed.push(name);
  }
  const stateFiles = [
    process.env.AIRELAY_SESSIONS || path.join(os.homedir(), '.airelay/sessions.json'),
    process.env.AIRELAY_HISTORY || path.join(os.homedir(), '.airelay/launch-history.json'),
    process.env.AIRELAY_DETACHED || path.join(os.homedir(), '.airelay/detached.json'),
  ];
  const inspect = (value: unknown, depth = 0): void => {
    if (depth > 8) throw new Error('Migration metadata depth limit exceeded.');
    if (!value || typeof value !== 'object') return;
    if ('profile' in value && removed.includes(String(value.profile)))
      throw new Error(
        `Profile ${value.profile} has saved/runtime references; migrate those explicitly before removal.`
      );
    for (const child of Object.values(value))
      if (typeof child === 'object') inspect(child, depth + 1);
  };
  for (const source of stateFiles) {
    if (!fs.existsSync(source)) continue;
    if (fs.statSync(source).size > 16 * 1024 * 1024)
      throw new Error('Migration metadata exceeds inspection limit.');
    inspect(JSON.parse(fs.readFileSync(source, 'utf8')));
  }
  if (process.platform === 'linux')
    for (const pid of fs.readdirSync('/proc').filter((n) => /^\d+$/.test(n))) {
      let args: string[];
      try {
        args = fs.readFileSync(`/proc/${pid}/cmdline`, 'utf8').split('\0');
      } catch {
        continue;
      }
      if (removed.some((name) => args.includes(name)))
        throw new Error('A generated profile is still used by a live process; no changes made.');
    }
  if (!removed.length) return { removed, dryRun };
  for (const name of removed) document.deleteIn(['profiles', name]);
  document.setIn(['settings', 'workspaceRoot'], root);
  ConfigSchema.parse(document.toJS());
  if (dryRun) return { removed, root, dryRun };
  const backups = path.join(path.dirname(file), 'backups');
  fs.mkdirSync(backups, { recursive: true, mode: 0o700 });
  const backup = path.join(backups, `workspace-profiles-${randomUUID()}`);
  backupWorkspaceConfiguration([file], backup);
  const temporary = `${file}.${randomUUID()}.tmp`;
  try {
    fs.writeFileSync(temporary, document.toString(), { flag: 'wx', mode: stat.mode & 0o777 });
    fs.chownSync(temporary, stat.uid, stat.gid);
    if (!fs.readFileSync(file).equals(before))
      throw new Error('Configuration changed during migration; nothing overwritten.');
    fs.renameSync(temporary, file);
  } finally {
    fs.rmSync(temporary, { force: true });
  }
  return { removed, root, dryRun, backup };
}
